<?php
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
if (empty($_SESSION["user"]) || (isset($_SESSION["expire"]) && time() > $_SESSION["expire"])) { header("Location: /index.php"); exit; }
include_once 'linker.php';
require_once __DIR__ . '/../models/EmpresaConfig.php';
if (strtolower(trim((string) ($_SESSION['user'] ?? ''))) !== 'superadmin') { include_once 'error/noAcceso.php'; exit; }
if (empty($_SESSION['vigencia_csrf'])) $_SESSION['vigencia_csrf'] = bin2hex(random_bytes(32));
$config = empresaConfigObtener(); $e = $config['empresa']; $m = $config['meta'];
function vh($v) { return htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); }
function vm($m, $k, $d = '') { return isset($m[$k]) ? $m[$k] : $d; }
$paisesSistema = array(
 'PE'=>array('nombre'=>'Perú','zona'=>'America/Lima'), 'CO'=>array('nombre'=>'Colombia','zona'=>'America/Bogota'),
 'EC'=>array('nombre'=>'Ecuador','zona'=>'America/Guayaquil'), 'BO'=>array('nombre'=>'Bolivia','zona'=>'America/La_Paz'),
 'CL'=>array('nombre'=>'Chile','zona'=>'America/Santiago'), 'AR'=>array('nombre'=>'Argentina','zona'=>'America/Argentina/Buenos_Aires'),
 'MX'=>array('nombre'=>'México','zona'=>'America/Mexico_City'), 'US'=>array('nombre'=>'Estados Unidos (Este)','zona'=>'America/New_York'),
 'ES'=>array('nombre'=>'España','zona'=>'Europe/Madrid')
);
$paisSistema = strtoupper(vm($m, 'sistema_pais', 'PE'));
if (!isset($paisesSistema[$paisSistema])) $paisSistema = 'PE';
$zonaSistema = $paisesSistema[$paisSistema]['zona'];
$tzSistema = new DateTimeZone($zonaSistema);
$ahoraSistema = new DateTime('now', $tzSistema);
$hoy = new DateTime('today', $tzSistema);
$desde = vm($m, 'vigencia_desde', $hoy->format('Y-m-d'));
$hasta = vm($m, 'vigencia_hasta', (clone $hoy)->modify('+30 days')->format('Y-m-d'));
$fin = DateTime::createFromFormat('!Y-m-d', $hasta, $tzSistema);
$dias = $fin ? (int) $hoy->diff($fin)->format('%r%a') : 0;
$cliente = vm($m, 'vigencia_cliente', vm($m, 'nombre_comercial', $e['RAZONSOCIAL'] ?? 'Cliente'));
$estado = strtoupper(vm($m, 'vigencia_estado_pago', 'PENDIENTE'));
$socialDesde = vm($m, 'social_desde', $hoy->format('Y-m-d'));
$socialHasta = vm($m, 'social_hasta', (clone $hoy)->modify('+7 days')->format('Y-m-d'));
$socialTipo = strtoupper(vm($m, 'social_tipo', 'FESTEJO'));
$socialMensaje = vm($m, 'social_mensaje', '¡Celebramos contigo! Gracias por ser parte de nuestra comunidad.');
$socialAvisos = json_decode(vm($m, 'social_avisos_json', '[]'), true);
if (!is_array($socialAvisos)) $socialAvisos = array();
if (!isset($m['social_avisos_json']) && !$socialAvisos && vm($m, 'social_mensaje', '') !== '') $socialAvisos[] = array('id'=>'aviso-inicial','activo'=>vm($m,'social_aviso_activo','0')==='1','tipo'=>$socialTipo,'icono'=>'star','mensaje'=>$socialMensaje,'desde'=>$socialDesde,'hasta'=>$socialHasta,'hora_inicio'=>vm($m,'social_hora_inicio','08:00'),'hora_fin'=>vm($m,'social_hora_fin','22:00'),'intervalo'=>(int)vm($m,'social_intervalo_minutos','30'),'duracion'=>(int)vm($m,'social_duracion_segundos','15'));
$mensaje = vm($m, 'vigencia_mensaje', 'Su servicio está próximo a vencer. Comuníquese con soporte para mantenerlo activo.');
?>
