  <section class="vg-preview"><h2>Vista previa del aviso</h2><div class="preview-banner" id="preview"><i class="fa fa-bell" style="display:grid;place-items:center;width:31px;height:31px;border-radius:10px;color:#fff;background:linear-gradient(135deg,#ef334f,#b91c1c);box-shadow:0 5px 14px rgba(185,28,28,.35)"></i><span class="preview-media <?php echo (vm($m,'vigencia_gif','')!==''||vm($m,'vigencia_emoji','')!=='')?'show':''; ?>"><?php if(vm($m,'vigencia_gif','')!==''): ?><img src="../<?php echo vh(ltrim(vm($m,'vigencia_gif',''),'/')); ?>" alt=""><?php else: ?><?php echo vh(vm($m,'vigencia_emoji','')); ?><?php endif; ?></span><span><b id="previewTitle">Renovación próxima:</b> <span id="previewText"><?php echo vh($mensaje); ?></span></span><span class="badge" id="previewDays"></span><span class="preview-media <?php echo (vm($m,'vigencia_gif','')!==''||vm($m,'vigencia_emoji','')!=='')?'show':''; ?>"><?php if(vm($m,'vigencia_gif','')!==''): ?><img src="../<?php echo vh(ltrim(vm($m,'vigencia_gif',''),'/')); ?>" alt=""><?php else: ?><?php echo vh(vm($m,'vigencia_emoji','')); ?><?php endif; ?></span></div></section>
  <section class="vg-social">
   <header class="vg-social-head"><i class="fa fa-star"></i><div><h2>Avisos de festejos y saludos</h2><p>Programa mensajes que recorrerán la pantalla de derecha a izquierda.</p></div></header>
   <div class="vg-form">
    <input type="hidden" name="social_avisos_json" id="socialAvisosJson" value="<?php echo vh(json_encode($socialAvisos, JSON_UNESCAPED_UNICODE)); ?>"><input type="hidden" id="socialEditIndex" value="">
    <input type="hidden" name="social_aviso_activo" id="socialActivo" value="1">
    <div class="vg-field"><label>Tipo de aviso</label><select name="social_tipo" id="socialTipo"><option value="FESTEJO" <?php echo $socialTipo==='FESTEJO'?'selected':''; ?>>Festejo</option><option value="SALUDO" <?php echo $socialTipo==='SALUDO'?'selected':''; ?>>Saludo</option><option value="INFORMATIVO" <?php echo $socialTipo==='INFORMATIVO'?'selected':''; ?>>Informativo</option></select></div>
    <div class="vg-field"><label>Icono animado</label><select id="socialIcono"><option value="star">Estrella</option><option value="heart">Corazón</option><option value="gift">Regalo</option><option value="birthday-cake">Cumpleaños</option><option value="bell">Campana</option><option value="smile-o">Sonrisa</option><option value="info-circle">Información</option></select></div>
    <div class="vg-field"><label>Emoji del aviso</label><select id="socialEmoji"><option value="">Sin emoji</option><?php foreach(array('🎉'=>'Fiesta','🎂'=>'Cumpleaños','🎁'=>'Regalo','🥳'=>'Celebración','✨'=>'Destello','❤️'=>'Corazón','👏'=>'Aplausos','📢'=>'Anuncio','😊'=>'Sonrisa') as $em=>$nom): ?><option value="<?php echo vh($em); ?>"><?php echo $em.' '.$nom; ?></option><?php endforeach; ?></select></div>
    <div class="vg-field"><label>GIF animado del aviso</label><input type="file" id="socialGif" accept="image/gif"><input type="hidden" id="socialGifActual" value=""><small style="color:var(--vg-muted)">Opcional, máximo 3 MB. Se guarda con esta programación.</small></div>
    <div class="vg-field"><label>Repetir cada (minutos)</label><input type="number" name="social_intervalo_minutos" min="1" max="1440" value="<?php echo vh(vm($m,'social_intervalo_minutos','30')); ?>"></div>
    <div class="vg-field vg-span"><label>Mensaje que recorrerá la pantalla</label><textarea name="social_mensaje" id="socialMensaje" placeholder="Ejemplo: ¡Feliz aniversario! Gracias por acompañarnos."><?php echo vh($socialMensaje); ?></textarea></div>
    <div class="vg-field"><label>Mostrar desde la fecha</label><input type="date" name="social_desde" id="socialDesde" value="<?php echo vh($socialDesde); ?>"><small style="color:var(--vg-muted)">Formato: día / mes / año.</small></div><div class="vg-field"><label>Mostrar hasta la fecha</label><input type="date" name="social_hasta" id="socialHasta" value="<?php echo vh($socialHasta); ?>"><small style="color:var(--vg-muted)">Debe ser igual o posterior a la fecha inicial.</small></div>
    <div class="vg-field"><label>Hora de inicio diaria</label><input type="time" name="social_hora_inicio" value="<?php echo vh(vm($m,'social_hora_inicio','08:00')); ?>"></div><div class="vg-field"><label>Hora de fin diaria</label><input type="time" name="social_hora_fin" value="<?php echo vh(vm($m,'social_hora_fin','22:00')); ?>"></div>
    <div class="vg-field"><label>Velocidad del recorrido (segundos)</label><input type="number" name="social_duracion_segundos" id="socialDuracion" min="5" max="120" value="<?php echo vh(vm($m,'social_duracion_segundos','15')); ?>"><small style="color:var(--vg-muted)">Menos segundos = más rápido.</small></div>
   </div>
   <div class="social-demo" id="socialDemo"><div class="social-demo-track" id="socialDemoTrack"><i class="fa fa-star"></i><span id="socialDemoText"><?php echo vh($socialMensaje); ?></span></div></div>
   <button class="vg-add-notice" id="agregarAviso" type="button"><i class="fa fa-plus"></i> Agregar programación</button><div class="vg-notice-list" id="socialNoticeList"></div>
  </section>
  <div class="vg-actions"><button class="vg-save" id="guardar" type="submit"><i class="fa fa-floppy-o"></i> Guardar configuración</button></div>
 </form>
</main><div class="vg-toast" id="toast"></div>
<script>
(function(){var form=document.getElementById('vigenciaForm'),desde=document.getElementById('desde'),hasta=document.getElementById('hasta'),fechaLimitePago=document.getElementById('fechaLimitePago'),estado=document.getElementById('estado'),cliente=document.getElementById('cliente'),mensaje=document.getElementById('mensaje');
function days(){var fecha=(fechaLimitePago&&fechaLimitePago.value)||hasta.value;if(!fecha)return 0;var a=new Date(),b=new Date(fecha+'T00:00:00');a.setHours(0,0,0,0);return Math.round((b-a)/86400000)}
function update(){var d=days(),preview=document.getElementById('preview');document.getElementById('statDias').textContent=d;document.getElementById('statCliente').textContent=cliente.value||'Cliente';document.getElementById('statEstado').textContent=estado.value;document.getElementById('previewText').textContent=mensaje.value;document.getElementById('previewTitle').textContent=d<0?'Servicio vencido:':'Renovación próxima:';document.getElementById('previewDays').textContent=d<0?'Venció hace '+Math.abs(d)+' día'+(Math.abs(d)===1?'':'s'):(d===0?'Vence hoy':'Quedan '+d+' día'+(d===1?'':'s'));preview.className='preview-banner '+(d<0?'expired':d<=7?'urgent':d>30?'info':'');document.getElementById('daysCard').classList.toggle('danger',d<0)}
[desde,hasta,fechaLimitePago,estado,cliente,mensaje].forEach(function(el){if(el)el.addEventListener('input',update)});document.getElementById('periodo').addEventListener('change',function(){if(!this.value)return;var base=new Date((desde.value||new Date().toISOString().slice(0,10))+'T00:00:00');base.setMonth(base.getMonth()+Number(this.value));hasta.value=base.toISOString().slice(0,10);update()});update();
var vigenciaEmoji=document.getElementById('vigenciaEmoji'),vigenciaGif=document.getElementById('vigenciaGif'),previewMedia=document.querySelectorAll('#preview .preview-media');
function previewEmoji(){previewMedia.forEach(function(media){media.innerHTML='';if(vigenciaEmoji.value){media.textContent=vigenciaEmoji.value;media.classList.add('show')}else media.classList.remove('show')})}
vigenciaEmoji.addEventListener('change',previewEmoji);vigenciaGif.addEventListener('change',function(){var file=this.files&&this.files[0];if(!file){previewEmoji();return}if(file.type!=='image/gif'){alert('Seleccione una imagen GIF válida.');this.value='';previewEmoji();return}if(file.size>3145728){alert('El GIF no puede superar los 3 MB.');this.value='';previewEmoji();return}var url=URL.createObjectURL(file);previewMedia.forEach(function(media){var img=document.createElement('img');img.alt='';img.src=url;media.innerHTML='';media.appendChild(img);media.classList.add('show')})});
var socialTipo=document.getElementById('socialTipo'),socialMensaje=document.getElementById('socialMensaje'),socialDuracion=document.getElementById('socialDuracion'),socialDemo=document.getElementById('socialDemo'),socialTrack=document.getElementById('socialDemoTrack');function updateSocial(){socialDemo.className='social-demo '+socialTipo.value.toLowerCase();document.getElementById('socialDemoText').textContent=socialMensaje.value||'Escribe el mensaje del aviso';socialTrack.style.animationDuration=Math.max(5,Number(socialDuracion.value)||15)+'s'}[socialTipo,socialMensaje,socialDuracion].forEach(function(el){el.addEventListener('input',updateSocial)});updateSocial();
 form.addEventListener('submit',function(e){e.preventDefault();var btn=document.getElementById('guardar'),add=document.getElementById('agregarAviso'),toast=document.getElementById('toast');btn.disabled=true;btn.innerHTML='<i class="fa fa-spinner fa-spin"></i> Guardando...';fetch('/controllers/ComunicadosVigenciaGuardar.php',{method:'POST',body:new FormData(form),credentials:'same-origin'}).then(function(r){return r.json().then(function(data){return {ok:r.ok,data:data}})}).then(function(result){toast.textContent=result.data.message;toast.className='vg-toast show'+(result.ok?'':' error');if(result.ok)setTimeout(function(){location.reload()},900)}).catch(function(){toast.textContent='No se pudo conectar con el servidor.';toast.className='vg-toast show error'}).finally(function(){btn.disabled=false;btn.innerHTML='<i class="fa fa-floppy-o"></i> Guardar comunicado';if(add){add.disabled=false;if(document.getElementById('socialEditIndex').value==='')add.innerHTML='<i class="fa fa-plus"></i> Agregar programación'}setTimeout(function(){toast.classList.remove('show')},4500)})});})();
</script>
<script>
(function(){
 var form=document.getElementById('vigenciaForm'),hidden=document.getElementById('socialAvisosJson'),list=document.getElementById('socialNoticeList'),edit=document.getElementById('socialEditIndex');
 var notices=[];try{notices=JSON.parse(hidden.value||'[]')}catch(e){notices=[]}if(!Array.isArray(notices))notices=[];notices.forEach(function(n){n.activo=true});
 var q=function(n){return form.querySelector('[name="'+n+'"]')},icon=document.getElementById('socialIcono'),emoji=document.getElementById('socialEmoji'),gif=document.getElementById('socialGif'),gifActual=document.getElementById('socialGifActual'),active=document.getElementById('socialActivo');
 var socialDesdeInput=q('social_desde'),socialHastaInput=q('social_hasta');function ordenarFechas(){if(!socialDesdeInput||!socialHastaInput)return;socialHastaInput.min=socialDesdeInput.value||'';if(socialDesdeInput.value&&socialHastaInput.value&&socialHastaInput.value<socialDesdeInput.value)socialHastaInput.value=socialDesdeInput.value}if(socialDesdeInput){socialDesdeInput.addEventListener('change',ordenarFechas);socialDesdeInput.addEventListener('input',ordenarFechas)}ordenarFechas();
 icon.addEventListener('change',function(){var demo=document.querySelector('#socialDemoTrack i');if(demo)demo.className='fa fa-'+icon.value});
 function safe(v){var d=document.createElement('div');d.textContent=v||'';return d.innerHTML}function sync(){hidden.value=JSON.stringify(notices)}
 function estadoAviso(n){var actual=<?php echo json_encode($ahoraSistema->format('Y-m-d H:i')); ?>,hoy=actual.slice(0,10),hora=actual.slice(11,16);if(hoy<n.desde)return'Programado';if(hoy>n.hasta)return'Finalizado';var hi=n.hora_inicio||'00:00',hf=n.hora_fin||'23:59',enHora=hi<=hf?(hora>=hi&&hora<=hf):(hora>=hi||hora<=hf);return enHora?'Activo ahora':'Fuera de horario'}
 function render(){sync();if(!notices.length){list.innerHTML='<div class="vg-notice-empty"><i class="fa fa-calendar-plus-o"></i> Todavía no hay avisos programados.</div>';return}list.innerHTML=notices.map(function(n,i){return '<article class="vg-notice-item"><span class="vg-notice-icon">'+(n.emoji?safe(n.emoji):'<i class="fa fa-'+safe(n.icono||'star')+'"></i>')+'</span><div class="vg-notice-copy"><strong>'+safe(n.mensaje)+'</strong><small>'+safe(n.desde)+' al '+safe(n.hasta)+' · '+safe(n.hora_inicio)+'–'+safe(n.hora_fin)+' · cada '+Number(n.intervalo)+' min · '+(n.gif?'GIF · ':'')+safe(estadoAviso(n))+'</small></div><div class="vg-notice-tools"><button class="vg-edit" type="button" data-edit="'+i+'" title="Editar aviso"><i class="fa fa-pencil"></i></button><button class="vg-delete" type="button" data-delete="'+i+'" title="Eliminar aviso"><i class="fa fa-trash"></i></button></div></article>'}).join('')}
 function read(){return{id:'aviso-'+Date.now(),activo:true,tipo:q('social_tipo').value,icono:icon.value,emoji:emoji.value,gif:gifActual.value,gif_data:'',mensaje:q('social_mensaje').value.trim(),desde:q('social_desde').value,hasta:q('social_hasta').value,hora_inicio:q('social_hora_inicio').value||'00:00',hora_fin:q('social_hora_fin').value||'23:59',intervalo:Number(q('social_intervalo_minutos').value)||30,duracion:Number(q('social_duracion_segundos').value)||15}}
 document.getElementById('agregarAviso').addEventListener('click',function(){var button=this,n=read(),file=gif.files&&gif.files[0];if(!n.mensaje||!n.desde||!n.hasta){alert('Complete el mensaje y las fechas del aviso.');return}if(n.hasta<n.desde){n.hasta=n.desde;q('social_hasta').value=n.hasta}n.activo=true;active.checked=true;if(file&&file.size>3145728){alert('El GIF no puede superar los 3 MB.');return}function saveNotice(){var i=edit.value===''?-1:Number(edit.value),wasEdit=i>=0;if(wasEdit){n.id=notices[i].id;notices[i]=n;edit.value='';button.innerHTML='<i class="fa fa-plus"></i> Agregar programación'}else notices.push(n);gif.value='';gifActual.value='';render();button.disabled=true;button.innerHTML='<i class="fa fa-spinner fa-spin"></i> Guardando...';setTimeout(function(){form.requestSubmit()},80)}if(file){var reader=new FileReader();reader.onload=function(){n.gif_data=reader.result;saveNotice()};reader.readAsDataURL(file)}else saveNotice()});
 list.addEventListener('click',function(e){
  var b=e.target.closest('button');if(!b)return;
  if(b.dataset.delete!==undefined){
   if(!confirm('¿Eliminar definitivamente este aviso programado?'))return;
   notices.splice(Number(b.dataset.delete),1);edit.value='';
   if(!notices.length){active.checked=false;q('social_mensaje').value='';document.getElementById('socialDemoText').textContent='Sin avisos programados'}
   render();setTimeout(function(){form.requestSubmit()},80);return;
  }
  if(b.dataset.edit!==undefined){var i=Number(b.dataset.edit),n=notices[i];edit.value=i;active.checked=!!n.activo;q('social_tipo').value=n.tipo;icon.value=n.icono;emoji.value=n.emoji||'';gifActual.value=n.gif||'';gif.value='';q('social_mensaje').value=n.mensaje;q('social_desde').value=n.desde;q('social_hasta').value=n.hasta;q('social_hora_inicio').value=n.hora_inicio;q('social_hora_fin').value=n.hora_fin;q('social_intervalo_minutos').value=n.intervalo;q('social_duracion_segundos').value=n.duracion;document.getElementById('agregarAviso').innerHTML='<i class="fa fa-check"></i> Actualizar programación';document.querySelector('.vg-social').scrollIntoView({behavior:'smooth'})}
 });
 form.addEventListener('submit',function(e){
  if(edit.value!==''){
   var i=Number(edit.value),n=read();
   if(!n.mensaje||!n.desde||!n.hasta){e.preventDefault();alert('Complete el mensaje y las fechas del aviso que está editando.');return}
   if(n.hasta<n.desde){n.hasta=n.desde;q('social_hasta').value=n.hasta}
   n.id=notices[i]&&notices[i].id?notices[i].id:n.id;n.activo=true;notices[i]=n;edit.value='';
  }
  notices.forEach(function(n){n.activo=true});sync();
 },true);render();
}());
</script></body></html>
